struct FieldMoveReplacement
{
    const struct Tileset *tileset; // the map's primary tileset
    u16 from;
    u16 to;
};

struct TreeMon
{
    u8 percent;
    u16 species;
    u8 level;
};

struct TreeMonSet
{
    const struct TreeMon *common; // TREEMON_COUNT entries
    const struct TreeMon *rare;
};

struct TreeMonMap
{
    u8 mapGroup;
    u8 mapNum;
    u8 set;
};

#include "data/johto_field_moves.h"

// VAR_RESULT = the first party slot that can use Whirlpool, or PARTY_SIZE.
// Same rule as the planned HM rework: HM09 in the bag, and a Pokemon that knows or can learn it.
void DittoFindWhirlpoolUser(void)
{
    u32 i;

    gSpecialVar_Result = PARTY_SIZE;
    if (!CheckBagHasItem(ITEM_HM09, 1))
        return;
    for (i = 0; i < PARTY_SIZE; i++)
    {
        struct Pokemon *mon = &gPlayerParty[i];
        u16 species = GetMonData(mon, MON_DATA_SPECIES_OR_EGG);

        if (species == SPECIES_NONE || species == SPECIES_EGG)
            continue;
        if (MonKnowsMove(mon, MOVE_WHIRLPOOL) || CanMonLearnTMHM(mon, ITEM_HM09 - ITEM_TM01))
        {
            gSpecialVar_Result = i;
            return;
        }
    }
}

static void FieldMoveShowMonDone(void)
{
    ScriptContext_Enable();
}

// Shows the Pokemon in field effect argument 0 using its move, like Cut and Rock Smash do.
// Follow with waitstate.
void DittoStartFieldMoveShowMon(void)
{
    u8 taskId = CreateFieldMoveTask();

    gTasks[taskId].data[8] = (u32)FieldMoveShowMonDone >> 16;
    gTasks[taskId].data[9] = (u32)FieldMoveShowMonDone;
}

void DittoClearWhirlpool(void)
{
    s16 x, y;
    u32 i, metatile;

    GetXYCoordsOneStepInFrontOfPlayer(&x, &y);
    metatile = MapGridGetMetatileIdAt(x, y);
    for (i = 0; i < ARRAY_COUNT(sWhirlpoolReplacements); i++)
    {
        if (sWhirlpoolReplacements[i].tileset == gMapHeader.mapLayout->primaryTileset
         && sWhirlpoolReplacements[i].from == metatile)
        {
            // The whirlpool comes back when the map reloads, as in Crystal.
            MapGridSetMetatileIdAt(x, y, sWhirlpoolReplacements[i].to);
            CurrentMapDrawMetatileAt(x, y);
            return;
        }
    }
}

enum { TREE_SCORE_BAD, TREE_SCORE_GOOD, TREE_SCORE_RARE };

// Crystal's GetTreeScore: each tree scores against the player's trainer ID, so
// different players find Pokemon in different trees.
static u32 GetTreeScore(s16 x, s16 y)
{
    // Crystal's map coordinates include a 4-block border; ours include MAP_OFFSET.
    u32 cx = x - MAP_OFFSET + 4;
    u32 cy = y - MAP_OFFSET + 4;
    u32 coordScore = ((cx * cy + cx + cy) / 5) % 10;
    u32 otId = gSaveBlock2Ptr->playerTrainerId[0] | (gSaveBlock2Ptr->playerTrainerId[1] << 8);
    u32 otScore = otId % 10;
    s32 diff = coordScore - otScore;

    if (diff == 0)
        return TREE_SCORE_RARE;
    if (diff < 0)
        diff += 10;
    return diff < 5 ? TREE_SCORE_GOOD : TREE_SCORE_BAD;
}

static const struct TreeMon *SelectTreeMon(const struct TreeMon *table)
{
    s32 roll = Random() % 100;
    u32 i;

    for (i = 0; i < TREEMON_COUNT; i++)
    {
        roll -= table[i].percent;
        if (roll < 0)
            return &table[i];
    }
    return NULL;
}

// VAR_RESULT = TRUE if a wild Pokemon was prepared for dowildbattle.
void DittoHeadbuttTree(void)
{
    s16 x, y;
    u32 i, score, chance;
    const struct TreeMonSet *set = NULL;
    const struct TreeMon *mon;

    gSpecialVar_Result = FALSE;
    for (i = 0; i < ARRAY_COUNT(sTreeMonMaps); i++)
    {
        if (sTreeMonMaps[i].mapGroup == gSaveBlock1Ptr->location.mapGroup
         && sTreeMonMaps[i].mapNum == gSaveBlock1Ptr->location.mapNum)
        {
            set = &sTreeMonSets[sTreeMonMaps[i].set];
            break;
        }
    }
    if (set == NULL)
        return;

    GetXYCoordsOneStepInFrontOfPlayer(&x, &y);
    score = GetTreeScore(x, y);
    chance = score == TREE_SCORE_RARE ? 8 : score == TREE_SCORE_GOOD ? 5 : 1; // out of 10
    if (Random() % 10 >= chance)
        return;
    mon = SelectTreeMon(score == TREE_SCORE_RARE ? set->rare : set->common);
    if (mon == NULL || mon->species == SPECIES_NONE)
        return;
    CreateScriptedWildMon(mon->species, mon->level, ITEM_NONE);
    gSpecialVar_Result = TRUE;
}
